import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Verify {public static void main(String[] args)throws Exception{int count=0;try(ZipFile z=new ZipFile(args[0])){for(ZipEntry e:Collections.list(z.entries())){if(!e.getName().endsWith(".class"))continue;ClassNode c=new ClassNode();new ClassReader(z.getInputStream(e).readAllBytes()).accept(c,0);if(c.name.equals("net/mcreator/doomsdaydecoration/port/PortedBlock")){MethodNode ctor=c.methods.stream().filter(m->m.name.equals("<init>")).findFirst().get();boolean registered=false;for(AbstractInsnNode i:ctor.instructions.toArray())if(i instanceof MethodInsnNode call){if(call.owner.equals("dev/zomboid/decor/Storage")&&call.name.equals("configure"))registered=true;if(call.getOpcode()==Opcodes.INVOKESPECIAL&&call.name.equals("<init>")){if(!registered)throw new AssertionError("Footprints must register before the superclass constructor even when factory is bypassed");break;}}}
for(MethodNode m:c.methods){if((m.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))!=0)continue;new Analyzer<>(new BasicVerifier()).analyze(c.name,m);count++;}}}System.out.println("Bytecode methods analyzed: "+count);}}
